INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter26-state-congress-movements', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p1", "partName": "Formation and Early Goals of State Congress", "bodyMd": "The **State Congress** was established in **1938**, with the objective of establishing responsible government (praja prabhutvam) within the Nizam''s dominion.\n\n**Winning trust — an early struggle:**\n\n*   Its leaders worked hard to convince the Nizam''s government that the State Congress was not a communal organisation.\n*   They also worked to convince fellow Muslim leaders that it had no links to the party politics of British India''s Congress.\n*   This effort bore little fruit before their labour even began to show results.\n\n**Siraj-ul-Hassan Tirmizi:**\n\n*   Played a prominent role in the Hyderabad freedom struggle.\n*   Was known among Congress circles as a Muslim leader who did not subscribe to religious separatism.\n*   Worked with unwavering courage against injustices done to Hyderabad State under the pretext of protecting minority interests.\n*   Fought resolutely against communal politics, suffering hardships and insults from fellow Muslims.\n*   Remained an uncompromising nationalist to the end.\n\n**Ittehad-ul-Muslimeen**, convinced that any form of responsible government in Hyderabad would lead to Hindu domination, opposed such a movement outright.\n\n*   **1939 onward:** circumstances gradually began to change.\n*   **1942:** Mahatma Gandhi launched the **Quit India** movement, which turned into a single unified movement across the whole of India.\n*   **3 June 1946:** taking note of the changing situation, the Nizam''s government banned the State Congress.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p2", "partName": "Chhatari''s Second Premiership and Communal Tension (1941–47)", "bodyMd": "*   **August 1941** — **Nawab Chhatari** became Prime Minister of the state, in place of Sir Akbar Hydari.\n*   **1942** — a grave incident occurred at **Dichpalli** village, Nizamabad district:\n    *   Christian missionaries were running a leprosy hospital there.\n    *   Some Muslim residents built a shed (\"chabutra\") within the hospital premises, gave it the shape of a mosque, and began holding congregational prayers there.\n    *   This was against hospital regulations, so health authorities demolished the structure.\n    *   To Ittehad-ul-Muslimeen, this small administrative act was seen as an attack on their faith.\n\n**The Bolarum riot:**\n\n*   Muslims began disorderly agitations.\n    \n*   Grigson, the Revenue and Police Minister, and the (European) Resident, were naturally sympathetic to the missionaries.\n    \n*   Neither Nawab Chhatari (a Muslim himself) nor his mostly-Muslim ministers could do anything about the matter.\n    \n*   Angered, Muslims attacked **Bolarum** — where the Resident''s residence (Grigson''s residence, now Greenlands) was located — carrying torches.\n    \n*   Chhatari''s cattle-shed was burned down.\n    \n*   Grigson himself was not found in Greenlands; his library and house were burned.\n    \n*   **Cause:** Even a single act of government administration (however necessary) sparked the belief that faith itself was under attack → **Effect:** Anarchic mob violence, attacks on official residences.\n    \n*   The government fired only a single shot that day, and the Razakar movement did not yet raise its head.\n    \n*   The Police Commissioner did not cooperate, so Grigson remained a silent spectator while the disturbances took their course.\n    \n*   This unchecked lawlessness eventually led to the removal of Nawab Chhatari.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p3", "partName": "Sir Mirza Ismail''s Premiership", "bodyMd": "Following this, **Sir Mirza Ismail** became Prime Minister.\n\n**Profile:**\n\n*   A nationalist, skilled in business/administration, with a modern outlook.\n*   Had earlier brought about progressive changes as Prime Minister of Mysore and Jaipur.\n*   His attempts to introduce modern reforms into the sluggish Hyderabad state did not succeed.\n*   Hyderabad''s Muslims nicknamed him **\"Thod-Phod Khan\"** (\"the break-and-demolish Khan\").\n*   His policies pleased neither Ittehad-ul-Muslimeen nor, ultimately, the Nizam''s own government.\n*   Unable to bear the resentment directed at him, he resigned as Prime Minister within a few months, in **May 1947**.\n*   After resigning, he advised the Nizam that Hyderabad should join the Indian Union — the Nizam rejected this advice.\n\n**Leadership change in Ittehad-ul-Muslimeen:**\n\n*   After Bahadur Yar Jung''s death, **Kasim Razvi** took over the leadership of Ittehad-ul-Muslimeen.\n*   Razvi practised law in Latur.\n*   A \"Razakar\" means, literally, a volunteer.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p4", "partName": "The First State Congress Conference and the Independence of India", "bodyMd": "*   By this time, the ban on the Congress had been lifted.\n    \n*   **8 May 1947** — under the presidency of **Swami Ramananda Tirtha**, the first general body meeting (Maha Sabha) of the State Congress was held at **Chikkadpally**, Hyderabad — among the largest public meetings in Hyderabad''s history.\n    \n*   Swami Ramananda Tirtha''s presidential address stirred the public, and the blood of the youth boiled with fervour.\n    \n*   That same day, Ittehad-ul-Muslimeen''s leaders raised the cry of an independent Hyderabad.\n    \n*   It was under Kasim Razvi''s leadership that the Razakar movement began.\n    \n*   **15 August 1947** — India attained independence, its free sun shining from the Himalayas to Cape Comorin.\n    \n*   But in the princely state of Hyderabad, the Nizam blocked out this independence, creating a dense darkness instead.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p5", "partName": "Mogilayya''s Sacrifice", "bodyMd": "**Background:**\n\n*   A day before India''s independence, the Nizam had already proclaimed himself independent.\n*   Because of this, the Nizam''s regime treated India''s national flag as a \"foreign\" flag.\n*   The **Andhra Mahasabha**, jointly with left-wing groups, resolved at Warangal fort to hoist the national flag; the **Andhra Jatiyapaksham** was formed for this purpose and carried out the flag-hoisting.\n\n**The incident:**\n\n*   One of the volunteers, **Mogilayya**, at 8 a.m., shouted slogans of \"Mahatma Gandhi ki Jai,\" \"Congress ki Jai,\" \"Trivarna Patakam ki Jai,\" and \"Bharat Mata ki Jai\" with great heroism.\n*   Everyone present joined the slogan-shouting, and the whole fort echoed with the sound.\n*   Two to three hundred armed goons then arrived at the spot.\n*   On seeing Mogilayya raising the slogans, the goons attacked him savagely with sticks.\n*   One of the assailants was cut and began bleeding.\n*   The mob of goons then rampaged through the town.\n*   The District Collector, who had come to Aminpet town, ordered the killer to be garlanded.\n*   The killer, with blood still on his hands, cheekily removed the garland and threw it upon his companions as they congratulated him, in open mockery.\n*   **The killer''s name was Sharif**, known by the epithet \"Lakshmi Pahalwan.\"\n\n**Aftermath:**\n\n*   No newspaper covered this incident. The murder of Mogilayya was no ordinary event — in normal times it would have set the whole country ablaze.\n*   This killing took place on **9 August 1946**, before Sir Mirza Ismail took charge as Prime Minister.\n*   It took Kaloji Narayana Rao a week''s time to fully take in the circumstances; the government did not permit him to bring the body along with him.\n*   Kaloji wrote fiery lines in protest after this incident. _\\[Telugu verse in the original source is omitted here.\\]_\n*   Police Minister Grigson, who arrived on a tour around this time, was seen leisurely photographing forts, gopurams, and temples rather than addressing the matter.\n*   In the police machinery, an official responsible for archaeology — not one accountable for law and order — was made to handle the case instead.", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p6", "partName": "British Policy and the Partition of the Country", "bodyMd": "**British strategy before departure:**\n\n*   The British imperialists, experienced in devious politics, created serious problems for the national government before leaving India.\n    \n*   In line with their imperial interests, they split the country into two — India and Pakistan.\n    \n*   Behind the scenes, they created political conspiracies so that the new national strength would not consolidate.\n    \n*   They had sown similar seeds of discord in Korea, Vietnam, Laos, and Germany.\n    \n*   **Cause:** The British wished not merely to divide the country, but to create domestic strife that would linger on even after their departure → **Effect:** A formal declaration on this line was issued on **3 March 1947**.\n    \n*   The declaration''s gist: princely rulers within India could, of their own accord, merge with Pakistan, merge with India, or declare independence.\n    \n*   With Sardar Patel''s courage and political wisdom, nearly all the princely states were merged into India without bloodshed.\n    \n*   In doing so, Patel added an eternal and enduring page to the history of free India.\n    \n\n**Communal calculations around Hyderabad:**\n\n*   A false narrative was spread that Hindus and Muslims were mutually hostile groups, keeping the Muslims, Majlis, and Kashmir issue linked to the question of Hyderabad''s merger.\n*   Hindus would suffer if Hyderabad were merged into Pakistan (on the pretext of being loyal partisans on both sides).\n*   Muslims did not wish for merger into India either.\n*   The Nizam therefore proclaimed that it would be best for his kingdom to remain independent.\n*   He announced this so-called independence through a special firman, concealing his territorial ambition and religious bigotry.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p7", "partName": "The Standstill Agreement", "bodyMd": "*   There was no public support for the Nizam''s declaration of independence.\n*   As soon as this became known, the Nizam began negotiations with the Government of India.\n*   He engaged the eminent British jurist **Sir Walter Monckton**, appointing him constitutional advisor at a fee of one lakh rupees per day.\n\n**Delegation to Delhi:**\n\n*   Sent to Delhi: Prime Minister Nawab Chhatari, constitutional advisor Sir Walter Monckton, and law secretary Aliyawar Jung.\n*   The Government of India stated firmly there would be no change to the conditions of **15 August 1947** — foreign affairs, defence, and communications would remain with the Government of India (the same arrangement as under the British era).\n*   This first, temporary arrangement was called the **Standstill Agreement**.\n\n**Three further concessions sought by Hyderabad:**\n\n1.  If war broke out between India and Pakistan, the Hyderabad government would remain neutral.\n2.  Hyderabad should have the power to appoint Agents-General in foreign countries.\n3.  Hyderabad should be free to act independently of anything the Government of India did regarding the Commonwealth.\n\n*   Governor-General Lord Mountbatten made clear that even a change of \"full stop, comma\" in the original agreement could not be permitted.\n*   The Hyderabad government appointed the celebrated engineer **Nawab Zain Yar Jung**, an extremely nationalistic and modest man, as its Agent-General in Delhi.\n*   There was, in fact, no need for such uproar over the Hyderabad matter: historically and geographically the independence claim was untenable, and it was only the Centre''s preoccupation with partition-related problems that gave Hyderabad the opening it exploited.\n\n**Signing and its aftermath:**\n\n*   The delegation the Nizam sent to Delhi accepted the Standstill Agreement, then returned to Hyderabad on **27 August** to seek the Nizam''s assent.\n*   Ittehad-ul-Muslimeen leader Qasim Razvi also went to see the Nizam, arguing he should not sign — that a firmer stance would make the Government of India accept Hyderabad''s terms — and tried to blame the Nizam for weakness.\n*   The Nizam, a seasoned, administratively astute politician, understood the risks of delay and had no wish to see matters spiral out of control.\n*   The night the signed letter was ready to be sent to Delhi, **50,000 unofficial armed Razakars** (funded by the state) surrounded Prime Minister Chhatari''s residence in a menacing demonstration.\n*   Humiliated, Chhatari did nothing about it, and **resigned on 1 November 1947**.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p8", "partName": "Change of Prime Ministers", "bodyMd": "*   The Nizam appointed **Mehdi Yar Jung** as temporary Prime Minister in Chhatari''s place.\n*   Mehdi Yar Jung actually submitted the agreement to the Government of India, against the Nizam''s wishes.\n*   Angered that Mehdi Yar Jung had done the very thing he did not want done, the Nizam insisted on removing him.\n*   Mehdi Yar Jung resigned, and the Nizam appointed **Laik Ali** as Prime Minister on **29 November 1947**.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p9", "partName": "Laik Ali and \"Nalayak\" (Incompetent) Deeds", "bodyMd": "\"Laik\" means one who is wise/competent — but this \"Laik\" man''s deeds turned out one after another to be entirely \"Nalayak\" (incompetent) ones.\n\n**Early missteps and conditions under his rule:**\n\n*   As soon as it took power, the Laik Ali government paid Pakistan a loan of **20 crore rupees** — a further source of unease for the Central Government, given ongoing negotiations with Pakistan over partition-related asset values worth crores of rupees.\n*   Many Muslims who came from the north during partition found rehabilitation in the Nizam''s state.\n*   Razakars ravaged homes street by street; the peace and security problem worsened further.\n*   A British sailor, notorious as \"the smuggler of the sea,\" secretly brought weapons into the state.\n*   The Government of India appointed **K.M. Munshi**, a great political thinker and writer, as its Agent-General in Hyderabad; he resided at Dakshin Sadan, Bolarum (now Raj Bhavan), and wrote the historic novel _Jai Somnath_ during his stay.\n*   In those days it was not the Nizam, nor Laik Ali, but the **Qasim Razvi regime** that actually governed the state.\n*   Razakar leaders boasted that \"the waves of the Bay of Bengal and the Arabian Sea would wash our Nizam''s feet,\" and that \"the flag ' WHERE chapter_slug = 'telangana-history-en-chapter26-state-congress-movements';
UPDATE theory_content SET concepts_json = concepts_json || 'of an unrivalled kingdom would fly over the Red Fort in Delhi.\"\n\n### Expenditure Incurred by the Laik Ali Government\n\n| Item | Expenditure |\n|---|---|\n| War preparations against the Indian Union | About 8 crore 60 lakh rupees |\n| Propaganda for an \"independent Hyderabad\" in India and abroad | 50 lakh rupees |\n| Advocacy for Hyderabad''s cause before the Security Council | 50 lakh rupees |\n| Deficit in state budget for 1947–48 (due to excessive military expenditure) | 4 crore rupees |\n\n*   The Nizam sought British government support at the UN Security Council over the Hyderabad issue, but British Prime Minister Attlee said Britain could not separate Hyderabad from India and could not support Hyderabad on this matter.\n\n**The assembly and the \"Abhyudaya Prajapaksham\":**\n\n*   The State Congress and other national parties boycotted the assembly.\n*   Wealthy men and jagirdars supporting the government, along with those seeking the perks of membership, got themselves elected unopposed.\n*   This group called itself the **\"Abhyudaya Prajapaksham\"** (\"progressive people''s party\") when the ministry was formed.\n*   **Pingali Venkatramireddy**, from this group, obtained a seat in Laik Ali''s cabinet.\n\n**Elder statesmen sidelined:**\n\n*   Most elder statesmen of the state withdrew, sidelined by the Razakars'' atrocities.\n    \n*   Ali Yavar Jung, Zain Yar Jung, Mehdi Nawaz Jung, and Hosh Yar Jung took their pensions and shut themselves indoors.\n    \n*   Sarwar Jung, who did not heed Razvi''s word, was frightened by Razvi into fleeing the state.\n    \n*   Some fanatics conceived the idea of turning Hyderabad into a \"South Pakistan.\"\n    \n*   A local university professor, Dr. Latif, proposed relocating Hyderabad''s Hindus to Madras and Madhya Pradesh, and bringing Muslims from those regions into Hyderabad, as an \"easy solution.\"\n    \n*   This impossible, fantastical proposal was not accepted.", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p10", "partName": "Kasim Razvi''s Communal Declarations", "bodyMd": "*   The entire government machinery fell into Kasim Razvi''s hands; he treated the \"Laik Ali\" government as his puppet, while being openly hostile to it.\n*   Thousands gathered to hear his communal speeches at Razakar assemblies. \n\nExamples of his declarations:  \n\n1.  \"A Hindu is a _kafir_ (infidel) — he worships stones and monkeys (laughter in the audience). He eats beef under the name of religion. He drinks cow urine. Can the state remain in the hands of such uncivilised people?\" (met with wild laughter and clapping).\n2.  \"Hyderabad will inevitably annex the surrounding districts. This Nizam''s rule is not confined to Hyderabad alone — Bidar too is under the Nizam.\"\n3.  \"I shall hoist the flag of an unrivalled kingdom over the Red Fort.\"\n4.  \"If ever any danger arises to Muslims'' existence, they will not spare people of other faiths.\"\n\n*   Such irresponsible declarations tested the patience of the Government of India.\n*   **4 May 1948** — the state government lifted the ban on the Communist Party.\n\n**Campbell Johnson''s mediation:**\n\n*   Lord Mountbatten, while still holding office, wished to resolve the Hyderabad problem and sent his press secretary **Campbell Johnson** to Hyderabad as special envoy.\n*   Johnson held extensive talks with the Nizam, Razvi, and Laik Ali.\n*   He argued that constitutional, Western practices had no relevance to Hyderabad.\n*   Razvi''s hatred toward Hindus extended even to Johnson.\n*   Gandhiji''s remark that \"Hindus, after killing their leaders, will later turn around and deify them\" (made regarding Razvi''s murderous plans) drew a disproportionate hatred from Razvi toward Gandhi as well.\n*   With this communal fanaticism, no fruitful negotiations took place — Razvi sought gain without loss, and the actual agreement remained an honoured-in-name-only document, violated repeatedly by the Hyderabad government.", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p11", "partName": "Currency Measures and Repression", "bodyMd": "*   **24 December 1947** — the Hyderabad government withdrew Indian currency from circulation in state trade.\n*   **27 December** — a currency ordinance repealed rule 17 of Act 1321 Fasli, which had required state trade transactions to occur only in state currency.\n*   Two more ordinances banned the export of gold — all intended to undermine the actual (Standstill) agreement.\n*   **18 September 1947** — entry into the state was restricted to Muslim refugees only.\n\n**Impact on Hindus:**\n\n*   Refugees who arrived seeking revenge, aided by Razakars, looted homes street by street; no village escaped their plunder.\n*   For protection of life and property, the state''s Hindus fled to neighbouring states.\n*   Sardar Patel told Parliament that 8,000 Hyderabad Hindus arrived in Madras state alone.\n*   The government warned that lands and properties left behind by those who fled Hyderabad must be returned to their owners by **15 May 1948**.\n*   **January 1948** — the Nizam''s government took over the Bhadrachalam Ramalayam village-grant land.", "free": false}, {"partNumber": 12, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p12", "partName": "Attacks on Border Villages", "bodyMd": "*   The frustrated state government began raiding Union-government villages along the border with the help of Razakars.\n*   Near Usmanabad district, Razakars raided a village called **Nanaj**; Union-government village guards killed eighteen Razakars in that incident.\n*   The humiliation of the Nanaj incident inflamed the fire of revenge in the state.\n*   **9 August 1948** — Razakars held a \"Nanaj mourning meeting\" at Jamrud Mahal Theatre, Hyderabad, and took an oath to avenge those killed.\n*   Twenty Razakars from Hyderabad State entered Madras district and looted 50,000 rupees'' worth of property — disclosed by Madras state''s Home Minister, Dr. Subbarayan, in the legislative assembly on **27 February 1948**.", "free": false}, {"partNumber": 13, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p13", "partName": "The Murder of Shoaib-Ullah Khan", "bodyMd": "**Background — the \"Rayyat\" and \"Imroze\" newspapers:**\n\n*   The \"**Rayyat**\" newspaper, which openly expressed independent views, was banned by the Nizam''s government.\n*   The same day, intelligence official Fazal Rasool Khan delivered the ban order to its office.\n*   Its editor, Mandumula Narasingarao, who had won public affection through his independent views, had to bow to the autocratic ruler''s orders. Shoaib worked as sub-editor there.\n*   With Narasingarao''s assistance, Shoaib set up the \"**Imroze**\" newspaper; its first issue was published on **15 November 1947**.\n*   Financial support came from Burgula Ramakrishna Rao; the Imroze office was later shifted into his own house.\n*   Circulation, and readership, grew gradually.\n\n**Shoaib''s stance against the Razakars:**\n\n*   Hyderabad state''s population then was **1 crore 56 lakh**, of which **20 lakh 70 thousand 312** were Muslims — only 5 lakh of whom supported the Razakars.\n*   Shoaib wrote that the Razakars'' \"unrivalled kingdom\" slogan was baseless propaganda supported only by that minority.\n*   In those days, nearly all Urdu newspapers backed the Razakars; Shoaib, young and alone, had the courage to expose their inhuman conduct.\n*   The Razakars came to see him as a thorn in their side.\n*   Razvi indirectly warned his followers that forces \"trying to shatter... and destroy our unity must be uprooted, root and branch,\" and spoke openly against Shoaib with a vengeful heart.\n\n**21 August 1948 — atrocities intensify:**\n\n*   With the ambition of establishing an Islamic state astride free India, the Nizam, egged on by the Razakars, subjected citizens to atrocities.\n*   The lives, property, and dignity of Hindus in particular depended on the Razakars'' whims.\n*   All Hindus in the city locked their doors by evening; after seven o''clock the streets became entirely deserted.\n*   Many Hindu families fled the state, abandoning everything.\n\n**The murder itself:**\n\n*   Chappal Bazaar (on the route to Kachiguda railway station) also went dark that night; only the part of Burgula Ramakrishna Rao''s house holding the Imroze office had lights burning.\n*   Shoaib, heading to his rented lodging at Mahmood Ismail Khan''s house in Koti, reached the Lingampalli crossroads near his own house at midnight.\n*   A group of men ran up from behind; one fired a pistol, and three bullets struck Shoaib, who fell.\n*   The assailants then slashed both of Shoaib''s arms with swords, and slashed the fallen Ismail as well, before fleeing in the darkness.\n\n**Aftermath:**\n\n*   Shoaib''s murder shocked national newspapers across the country.\n*   Nehru, who had until then treated Hyderabad''s affairs as merely a Hindu–Muslim problem, gradually began to grasp the reality — this led the way toward Police Action.\n\n**Press censorship:**\n\n*   **8 February 1948** — the Nizam government ordered the Deccan Chronicle, Imroze, Payam, and Daily News to submit editorials, criticism, and letters to the editor to the censor before publication.\n*   The Golconda newspaper was barred from writing editorials for nearly two months.\n*   **28 March 1948** — State Congress women volunteers observed a 24-hour fast in protest; this was reported in Madras''s \"Hindu\" newspaper but remained unknown within Hyderabad.\n\n**The Muslim leaders'' memorial:**\n\n*   Seven Muslim leading citizens submitted a memorial to the Nizam urging steps to restore normalcy and peace, following the state''s suffering over Hyderabad''s proposed merger into the Indian Union.\n*   Signatories: Nawab Manjoor Jung (former Subedar, close to the Nizam), Mahmood Hussain Zafari (Director of Education), Farid Mirza (a Tehsildar who resigned his post to sign), Bakr Ali Mirza (educated abroad), Mullah Abdul Basit, Ahmed Mirza, Hussain Abdul Munir, and Mir Ahmed Alikhan.\n*   Their memorial created a sensation in Delhi; Sardar Patel forwarded a copy to the U.N.O.\n*   The signatories lived afterward in fear of losing their lives for this act.\n*   **30 January 1948** — Mahatma Gandhi''s assassination plunged the whole country into darkness.", "free": false}, {"partNumber": 14, "conceptId": "telangana-history-en-chapter26-state-congress-movements-p14", "partName": "Aftermath: Judicial Proceedings", "bodyMd": "*   Judges ruled that, given the extraordinary conditions prevailing in Hyderabad State, cases could not be heard in court there — an unprecedented occurrence.\n*   Even during India''s non-cooperation movement era, a boycott of the courts had earlier been carried out here in full measure.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter26-state-congress-movements';
